      out.write("\t\t\t\ttotal+=toNumber(t.getText(i,cols.amount));\r\n");
      out.write("\t\t\t\tif(taxes[roundOff(toNumber(t.getText(i,cols.taxperc)),2)]==undefined){\r\n");
      out.write("\t\t\t\t\ttaxes[roundOff(toNumber(t.getText(i,cols.taxperc)),2)]=0;\r\n");
      out.write("\t\t\t\t}\r\n");
      out.write("\t\t\t\ttaxes[roundOff(toNumber(t.getText(i,cols.taxperc)),2)]=taxes[roundOff(toNumber(t.getText(i,cols.taxperc)),2)]+toNumber(t.getText(i,cols.taxamt));\t\t\t\t\r\n");
      out.write("\t\t\t\ttotalDisc+=toNumber(t.getText(i,cols.discount));\r\n");
      out.write("\t\t\t\tnetTotal+=toNumber(t.getText(i,cols.netamount));\r\n");
      out.write("\t\t\t}\r\n");
      out.write("\t\t\tscreenObjects.getScreenObject(\"totalamount\").setValue(roundOff(total,2));\r\n");
      out.write("\t\t\tscreenObjects.getScreenObject(\"totaldiscount\").setValue(roundOff(totalDisc,2));\r\n");
      out.write("\t\t\tscreenObjects.getScreenObject(\"nettotalamount\").setValue(roundOff(netTotal,2));\r\n");
      out.write("\t\t\t//calculate the total taxes & other amounts\r\n");
      out.write("\t\t\tvar tg=screenObjects.getScreenObject(\"taxgrid_data\");\r\n");
      out.write("\t\t\tvar tgCols=tg.getCols();\r\n");
      out.write("\t\t\ts=tg.getSize();\r\n");
      out.write("\t\t\tvar ls_tax_type=screenObjects.getScreenObject(\"taxtype\").getValue();\r\n");
      out.write("\t\t\tvar ls_vat_type=screenObjects.getScreenObject(\"vattype\").getValue();\r\n");
      out.write("\t\t\tfor(var i=0;i<s;i++){\r\n");
      out.write("                var lc_amt = 0\r\n");
      out.write("                if(toNumber(tg.getText(i, tgCols.perc)) > 0){\r\n");
      out.write("                    if(tg.getText(i, tgCols.cr_dr) == \"C\"){\r\n");
      out.write("                        if(tg.getText(i, tgCols.basic_others) == \"B\"){\r\n");
      out.write("                            if(toNumber(tg.getText(i, tgCols.divid)) > 0){\r\n");
      out.write("                                if((ls_tax_type!=\"V\") && (ls_vat_type!=\"V\" || ls_vat_type!=\"N\")){\r\n");
      out.write("                                    if(toNumber(tg.getText(i, tgCols.divid)) > 0){\r\n");
      out.write("                                        tg.setText(i, tgCols.taxamount, roundOff(((netTotal * toNumber(tg.getText(i, tgCols.perc)) / 100) * toNumber(tg.getText(i, tgCols.divid)) / 100), 0));\r\n");
      out.write("                                    }else{\r\n");
      out.write("                                        tg.setText(i, tgCols.taxamount, roundOff(((netTotal * toNumber(tg.getText(i, tgCols.perc)) / 100)), 0));\r\n");
      out.write("                                    }\r\n");
      out.write("                                }\r\n");
      out.write("                            }else{\r\n");
      out.write("                                if((ls_tax_type!=\"V\") && (ls_vat_type!=\"V\" || ls_vat_type !=\"N\")){\r\n");
      out.write("                                \ttg.setText(i, tgCols.taxamount, roundOff(((netTotal * toNumber(tg.getText(i, tgCols.perc)) / 100)), 0));\r\n");
      out.write("                                }\r\n");
      out.write("                            }\r\n");
      out.write("\r\n");
